(window.FREALLY_I18N = window.FREALLY_I18N || {})["hi"] = {"hero.headline":"<span class=\"hl-muted\">असली हाथों को अपना संगीत बजाते देखें।</span> <span class=\"cycle\" data-cycle=\"hero.cycle\" data-words=\"Then drag it into your DAW.|Read every note.|Learn how it is played.\">फिर इसे अपने DAW में खींचें।</span>","hero.cycle":"फिर इसे अपने DAW में खींचें।|हर नोट पढ़ें।|सीखें कि इसे कैसे बजाया जाता है।","hero.sub":"कॉर्ड्स, एक धुन, एक बेसलाइन और एक काउंटरमेलोडी, किसी भी शैली में लिखे गए, शीट म्यूज़िक के चार पन्नों के रूप में दिखाए गए और यथार्थवादी हाथों द्वारा एक यथार्थवादी पियानो पर बजाए गए। ऑफ़लाइन और 100% AI-मुक्त।","hero.chipStandalone":"स्टैंडअलोन","what.title":"यह क्या है","what.p1":"कॉर्ड जनरेटर इस्तेमाल करने वाले ज़्यादातर प्रोड्यूसर कभी नहीं देखते कि उसके हिस्से कैसे बजाए जाएँगे। Handscore आपको दिखाता है।","what.p2":"कोई जॉनर, कलाकार या प्रोड्यूसर चुनें और Handscore उस शैली में चार हिस्से लिखता है: कॉर्ड्स, एक धुन, एक बेसलाइन और एक काउंटरमेलोडी। वे पियानो के म्यूज़िक स्टैंड पर शीट म्यूज़िक के चार पन्नों के रूप में दिखते हैं, और यथार्थवादी हाथों की एक जोड़ी उन्हें एक यथार्थवादी पियानो पर बजाती है, हर उंगली उसी कुंजी पर जिसे कोई पियानोवादक इस्तेमाल करता।","what.p3":"हर कुंजी अपना नाम अपने सामने वाले हिस्से पर रखती है, ताकि आप ठीक-ठीक देख सकें कि कौन-से नोट बजाए जा रहे हैं। जब कोई हिस्सा सही लगे, तो उसे उसकी शीट से सीधे अपने DAW के किसी ट्रैक पर खींच लें।","inside.title":"यह क्या करेगा","inside.pianos.title":"असली पियानो","inside.pianos.body":"एक ग्रैंड, एक अकूस्टिक, एक अपराइट और एक होंकी-टोंक पियानो, हर एक उन्हीं मापी गई पियानो आवाज़ों पर बजाया गया जिन पर Freally MIDI Master बजता है।","inside.hands.title":"यथार्थवादी हाथ","inside.hands.body":"दो हाथ जो हर नोट उसी उंगली से बजाते हैं जो कोई पियानोवादक चुनता, और हर कुंजी को उसके बजते ही नीचे दबाते हैं।","inside.sheets.title":"शीट म्यूज़िक के चार पन्ने","inside.sheets.body":"कॉर्ड्स, धुन, काउंटरमेलोडी और बास, हर एक अपनी अलग शीट पर, और हर नोट बजते समय रोशन होता है।","inside.styles.title":"हर शैली जिसे Freally MIDI Master जानता है","inside.styles.body":"73 जॉनर, 1,507 कलाकार और 833 प्रोड्यूसर, उन्हीं नियम-आधारित जनरेटरों से।","inside.drag.title":"MIDI खींचें","inside.drag.body":"एक बार में एक हिस्सा या चारों एक साथ, शीट्स से सीधे आपके DAW में खींचे गए। MIDI के Handscore से बाहर जाने का यही एकमात्र तरीका है।","inside.views.title":"सामने, ऊपर और बगल के व्यू","inside.views.body":"संगीत बजते समय इनके बीच बदलें; शीट्स पढ़ने लायक बने रहने के लिए घूम जाती हैं और हाथ कभी कोई नोट नहीं चूकते।","inside.daw.title":"किसी भी DAW में","inside.daw.body":"CLAP, VST3 और AU, साथ ही एक स्टैंडअलोन ऐप। Windows, macOS और Linux।","inside.offline.title":"ऑफ़लाइन, बिना AI","inside.offline.body":"कोई खाता नहीं, कोई टेलीमेट्री नहीं, कोई नेटवर्क नहीं, कोई मॉडल नहीं। हर हिस्सा, फ़िंगरिंग और हरकत नियमों से आती है, जिसे केवल वादा नहीं बल्कि एक बिल्ड गेट लागू करवाता है।","ladder.title":"1.0 की ओर रास्ता, और आगे 2.0 तक","ladder.intro":"हर संस्करण के लिए एक पंक्ति। 1.0 के बाद, हर संस्करण वाद्यों का एक नया परिवार लाता है, जिन्हें यथार्थवादी हाथ वैसे बजाते हैं जैसे कोई शिक्षक आपको दिखाता।","ladder.rung.v0.1.0":"नींव: प्लगइन CLAP, VST3 और AU के रूप में और स्टैंडअलोन ऐप के रूप में लोड होता है, अपने लाइसेंस की स्वीकृति माँगता है, और 88 कुंजियों वाले कीबोर्ड पर खुलता है जिसकी हर कुंजी का नाम लिखा है।","ladder.rung.v0.2.0":"असली पियानो: ग्रैंड, अकूस्टिक, अपराइट और होंकी-टोंक, बजते समय उनकी कुंजियाँ हिलती और बजती हैं।","ladder.rung.v0.3.0":"कीबोर्ड पर यथार्थवादी हाथ, हर नोट की फ़िंगरिंग वैसे ही करते हुए जैसे कोई पियानोवादक करता।","ladder.rung.v0.4.0":"किसी भी शैली में जनरेट करें, चारों शीट्स को रोशन होते हुए पढ़ें, और MIDI को अपने DAW में खींचें।","ladder.rung.v0.5.0":"ऊपर और बगल के व्यू, शीट्स पियानो पर सपाट रखी हुई, और व्यू के बीच सहज बदलाव।","ladder.rung.lessons-1":"पहले दिन से पाठ: एक पियानो कोर्स जो आपको बजाते हुए सुनता है और आपके सही बजाने पर आगे बढ़ता है, हर पाठ ज़ोर से पढ़कर सुनाया जाता है और बोले जाते समय हर शब्द रोशन होता है।","ladder.rung.mixer":"हर हिस्से के लिए एक मिक्सर, फ़ेडर, पैन, EQ, इफ़ेक्ट्स और कंप्रेशन के साथ, और खींचने पर भी मिक्स बना रहता है।","ladder.rung.song-view":"सॉन्ग व्यू: सेक्शन-दर-सेक्शन ख़ुद एक पूरा गाना बनाएँ, या किसी कलाकार या जॉनर के अरेंजमेंट से शुरुआत करें, फिर उसे बजते हुए देखें और अपने DAW में खींच लें।","ladder.rung.lessons-2":"और कोर्स: शीट म्यूज़िक पढ़ना, रिदम, ईयर ट्रेनिंग, Nashville Number System के साथ म्यूज़िक थ्योरी, सॉन्गराइटिंग और गीत के बोल, अरेंजिंग और मिक्सिंग।","ladder.rung.finger-drumming":"एक पैड कंट्रोलर पर फ़िंगर ड्रमिंग, जिसके पैड हर हिट पर रोशन होते हैं, पहली बीट से लेकर पूरे ग्रूव तक।","ladder.rung.live-listening":"लाइव लिसनिंग: किसी असली वाद्य को माइक्रोफ़ोन या इंस्ट्रूमेंट केबल के ज़रिए बजाएँ, और पाठ उसे सुनते हैं।","ladder.rung.guitars":"गिटार: अकूस्टिक, नायलॉन, इलेक्ट्रिक और म्यूटेड, असली फ़्रेटिंग, पिकिंग और स्ट्रमिंग के साथ।","ladder.rung.bass":"बास गिटार, उंगलियों से बजाया गया और स्लैप किया गया।","ladder.rung.own-audio":"आपका अपना ऑडियो और MIDI, हिस्सों में पढ़ा गया और हाथों द्वारा बजाया गया।","ladder.rung.classics":"क्लासिक्स: देखने और सुनने के लिए पब्लिक-डोमेन धुनें।","ladder.rung.realism":"यथार्थवाद का दौर: रोशनी, मटीरियल और हरकत, फ़िल्माए गए वादन की कसौटी पर।","ladder.rung.finish":"अंतिम रूप: सेटिंग्स, हर जगह अठारह भाषाएँ, सुगम्यता और मैनुअल।","ladder.rung.v1.0.0-beta.1":"अपडेट सूचनाएँ और ट्रायल तथा पेड संस्करण।","ladder.rung.v1.0.0":"पहली सार्वजनिक रिलीज़।","ladder.rung.v1.1.0":"इलेक्ट्रिक पियानो और ऑर्गन, ऑर्गन बेसलाइन के लिए पेडलबोर्ड के साथ।","ladder.rung.v1.2.0":"हार्प्सीकॉर्ड, क्लैविनेट, चेलेस्टा और खिलौना पियानो; यूकुलेले, बैंजो और मैंडोलिन।","ladder.rung.v1.3.0":"मैलेट वाद्य: ज़ाइलोफ़ोन, मरिम्बा, वाइब्राफ़ोन और ग्लॉकेनस्पील।","ladder.rung.v1.4.0":"हार्प, कोटो, सितार और माउंटेन डल्सिमर।","ladder.rung.v1.5.0":"वायलिन, वायोला, चेलो और डबल बास, गज़ से और उंगलियों से छेड़कर।","ladder.rung.v1.6.0":"फ़्लूट, क्लैरिनेट, सैक्सोफ़ोन, ओबो और रिकॉर्डर।","ladder.rung.v1.7.0":"ट्रम्पेट, ट्रॉम्बोन, फ़्रेंच हॉर्न और ट्यूबा।","ladder.rung.v1.8.0":"एक ड्रम किट, जिसे वैसे ही सेट किया और बजाया गया है जैसे कोई पेशेवर ड्रमर करता।","ladder.rung.v1.9.0":"साथ बजाने और सीखने का मोड।","ladder.rung.v2.0.0":"बैंड: हर हिस्सा अपने वाद्य पर, हर एक का अपना वादक।","ladder.note":"जो संस्करण पूरा हो चुका है वह बना और टैग किया गया है। यह डाउनलोड नहीं है: 1.0.0 से पहले कोई डाउनलोड नहीं है।","honest.title":"आज यह कहाँ है","honest.start.title":"यह अभी बिल्कुल शुरुआत में है","honest.start.body":"संस्करण 0.2.0 किसी DAW में लोड होता है और चार असली पियानो पर खुलता है, जिनकी हर कुंजी का नाम लिखा है और जिन्हें आप माउस से या अपने DAW से बजाते हैं। हाथ और शीट्स संस्करण-दर-संस्करण आते हैं, जैसा ऊपर की सीढ़ी दिखाती है।","honest.downloads.title":"1.0.0 से पहले कोई डाउनलोड नहीं है","honest.downloads.body":"इस पन्ने पर कोई बीटा नहीं, कोई प्रीव्यू बिल्ड नहीं और कोई शुरुआती पहुँच नहीं।","honest.network.title":"यह कभी ऑनलाइन नहीं जाता","honest.network.body":"प्लगइन और स्टैंडअलोन ऐप में कोई नेटवर्किंग कोड नहीं है, और अगर कभी जोड़ा भी जाए तो एक बिल्ड गेट फेल हो जाता है। किसी आगामी संस्करण में एक अपडेट-चेक जोड़ा जा सकता है, जो तब तक बंद रहेगा जब तक आप उसे चालू न करें, और जिसे एक अलग प्रोग्राम चलाएगा।","site.tagline":"असली हाथों को अपना संगीत बजाते देखें। फिर इसे अपने DAW में खींचें।","footer.licence":"स्वामित्व वाला — सर्वाधिकार सुरक्षित। © 2026 Mike Weaver, जो Havoc Software नाम से व्यापार करते हैं। ओपन सोर्स नहीं।","footer.yours":"आप जो MIDI बनाते हैं और अपने DAW में खींचते हैं, वह आपका है। Handscore के लेखक उस पर कोई स्वामित्व का दावा नहीं करते।","featuresPage.lead":"किसी भी शैली में लिखे चार हिस्से, शीट म्यूज़िक के रूप में दिखाए गए और यथार्थवादी हाथों द्वारा एक यथार्थवादी वाद्य पर बजाए गए — और हर हिस्सा सीधे आपके DAW में खिंच जाता है।","featuresPage.version":"यह पन्ना बताता है कि Freally Handscore संस्करण 1.0 क्या करेगा। आज का संस्करण 0.2.0 है: होम पेज पर 1.0 की ओर रास्ता देखें।","featuresPage.numbers.parts":"हिस्से: कॉर्ड्स, धुन, काउंटरमेलोडी और बास","featuresPage.numbers.genres":"जॉनर","featuresPage.numbers.artists":"कलाकार","featuresPage.numbers.producers":"प्रोड्यूसर","featuresPage.numbers.keys":"कुंजियाँ, हर एक का नाम उसके सामने वाले हिस्से पर","featuresPage.numbers.plugins":"प्लगइन फ़ॉर्मैट, साथ में एक स्टैंडअलोन ऐप","featuresPage.numbers.languages":"भाषाएँ","featuresPage.numbers.ai":"AI मॉडल","featuresPage.free.title":"आज मुफ़्त","featuresPage.free.body":"Handscore आज मुफ़्त है: कोई पेड टियर नहीं, कोई सब्सक्रिप्शन नहीं और कोई खाता नहीं। अभी डाउनलोड करने को कुछ नहीं है, क्योंकि संस्करण 1.0.0 से पहले कोई डाउनलोड नहीं है, और बाद के संस्करण बेचे जा सकते हैं।","featuresPage.cards.title":"संस्करण 1.0 क्या करता है","featuresPage.cards.pianos.title":"चार असली पियानो","featuresPage.cards.pianos.body":"एक ग्रैंड, एक अकूस्टिक, एक अपराइट और एक होंकी-टोंक पियानो, हर एक की कुंजियाँ बजते समय हिलती हैं, और उन्हीं मापी गई पियानो आवाज़ों पर बजाया गया जिन पर Freally MIDI Master बजता है।","featuresPage.cards.strings.title":"गिटार और बास गिटार","featuresPage.cards.strings.body":"अकूस्टिक, नायलॉन, इलेक्ट्रिक और म्यूटेड गिटार, असली फ़्रेटिंग, पिकिंग और स्ट्रमिंग के साथ, और बास गिटार, उंगलियों से बजाया गया और स्लैप किया गया।","featuresPage.cards.hands.title":"यथार्थवादी हाथ","featuresPage.cards.hands.body":"दो हाथ जो हर नोट वैसे ही बजाते हैं जैसे कोई वादक बजाता: वही उंगली जो कोई पियानोवादक चुनता, वही फ़्रेट और स्ट्रोक जो कोई गिटारवादक इस्तेमाल करता।","featuresPage.cards.sheets.title":"शीट म्यूज़िक के चार पन्ने","featuresPage.cards.sheets.body":"कॉर्ड्स, धुन, काउंटरमेलोडी और बास, हर एक अपनी अलग शीट पर, और हर नोट बजते समय रोशन होता है।","featuresPage.cards.styles.title":"हर शैली जिसे Freally MIDI Master जानता है","featuresPage.cards.styles.body":"73 जॉनर, 1,507 कलाकारों या 833 प्रोड्यूसरों में से एक चुनें, और वही नियम-आधारित जनरेटर उस शैली में चारों हिस्से लिखते हैं।","featuresPage.cards.yours.title":"आपका अपना ऑडियो और MIDI","featuresPage.cards.yours.body":"अपना ऑडियो या MIDI लाएँ, और Handscore उसे हिस्सों में पढ़ता है ताकि हाथ उन्हें बजा सकें।","featuresPage.cards.classics.title":"क्लासिक्स","featuresPage.cards.classics.body":"देखने और सुनने के लिए पब्लिक-डोमेन रचनाएँ। इन्हें सिर्फ़ बजाया जाता है, और ये कभी Handscore से बाहर नहीं जातीं।","featuresPage.cards.drag.title":"MIDI खींचें","featuresPage.cards.drag.body":"एक बार में एक हिस्सा या चारों एक साथ, शीट्स से सीधे आपके DAW में खींचे गए। MIDI के Handscore से बाहर जाने का यही एकमात्र तरीका है।","featuresPage.cards.views.title":"सामने, ऊपर और बगल के व्यू","featuresPage.cards.views.body":"संगीत बजते समय इनके बीच बदलें; शीट्स पढ़ने लायक बने रहने के लिए घूम जाती हैं और हाथ कभी कोई नोट नहीं चूकते।","featuresPage.cards.daw.title":"किसी भी DAW में","featuresPage.cards.daw.body":"Windows, macOS और Linux पर CLAP और VST3, macOS पर AU, और बिना DAW के काम करने के लिए एक स्टैंडअलोन ऐप।","featuresPage.cards.offline.title":"ऑफ़लाइन, बिना AI","featuresPage.cards.offline.body":"कोई खाता नहीं, कोई टेलीमेट्री नहीं, कोई नेटवर्क नहीं और कोई मॉडल नहीं। हर हिस्सा, फ़िंगरिंग और हरकत नियमों से आती है।","featuresPage.compare.title":"आमने-सामने","featuresPage.compare.intro":"Freally Handscore 1.0 उन औज़ारों के बगल में, जिनसे लोग संगीत के हिस्से लिखते हैं या पियानो बजते हुए देखते हैं। दूसरे उत्पादों के सेल उनकी सार्वजनिक लिस्टिंग और समीक्षाओं से लिए गए हैं, जिन्हें अक्टूबर 2026 में जाँचा गया; जहाँ हम किसी बात की पुष्टि नहीं कर सके, वहाँ सेल यही बताता है।","featuresPage.compare.feature":"फ़ीचर","featuresPage.compare.row.generate":"नामित शैलियों में नए कॉर्ड्स, धुनें और बेसलाइन लिखता है","featuresPage.compare.legend.yes":"उपलब्ध","featuresPage.compare.legend.no":"उपलब्ध नहीं","featuresPage.compare.row.plugin":"प्लगइन के रूप में आपके DAW के अंदर चलता है","featuresPage.compare.row.hands":"नोट बजाते हुए यथार्थवादी 3D हाथ दिखाता है","featuresPage.compare.note.library":"रचनाओं की अपनी लाइब्रेरी","featuresPage.compare.legend.part":"आंशिक","featuresPage.compare.note.fingers":"उंगलियों के नंबर, हाथ नहीं","featuresPage.compare.row.sheets":"नोट्स को शीट म्यूज़िक के रूप में दिखाता है","featuresPage.compare.legend.unknown":"पुष्टि नहीं हुई","featuresPage.compare.row.drag":"MIDI को आपके DAW में खींचता है","featuresPage.compare.row.offline":"ऑफ़लाइन, बिना AI के काम करता है","featuresPage.compare.summaryTitle":"संक्षेप में","featuresPage.compare.summary":"इन चारों में से सिर्फ़ Handscore 1.0 में हर पंक्ति है: नामित शैलियों में लिखे हिस्से, उन्हें बजाते यथार्थवादी हाथ, शीट म्यूज़िक, आपके DAW में खींचना और प्लगइन।","featuresPage.compare.theyWinTitle":"वे कहाँ आगे हैं","featuresPage.compare.theyWin":"Scaler 3 कहीं ज़्यादा व्यापक म्यूज़िक-थ्योरी वर्कस्टेशन है। Synthesia आपके अपने कीबोर्ड पर बजाना सीखने के लिए बना है, जिसे Handscore संस्करण 1.9 पर छोड़ता है। AR Pianist ऑगमेंटेड रियलिटी में अपने पियानोवादक को आपके कमरे में ले आता है, जो Handscore नहीं करता।","featuresPage.compare.fineprint":"Scaler, AR Pianist और Synthesia अपने-अपने मालिकों के ट्रेडमार्क हैं, जो Freally Handscore से संबद्ध नहीं हैं। अगर कोई सेल ग़लत हो तो हमें बताएँ, हम उसे ठीक कर देंगे।","featuresPage.why.title":"यह ऐसे क्यों बना है","featuresPage.why.rules.title":"नियम, मॉडल नहीं","featuresPage.why.rules.body":"हर हिस्सा, हर फ़िंगरिंग और हर हरकत नियमों से आती है, कहीं भी कोई मॉडल नहीं। वही शैली और वही सीड हर बार वही हिस्से देते हैं।","featuresPage.why.drag.title":"जो दिखता है, वही खिंचता है","featuresPage.why.drag.body":"शीट्स उसी MIDI से बनाई जाती हैं जिसे वे खींचती हैं, और हाथ ठीक वही नोट बजाते हैं, इसलिए आपके ट्रैक पर वही पहुँचता है जो आपने देखा।","featuresPage.why.real.title":"असली माप पर बना","featuresPage.why.real.body":"कीबोर्ड असली पियानो के आकार का है, और हर कुंजी अपने संतुलन बिंदु पर वैसे ही घूमती है जैसे असली कुंजी।","featuresPage.why.local.title":"यह आपकी मशीन पर ही रहता है","featuresPage.why.local.body":"कोई खाता नहीं, कोई टेलीमेट्री नहीं और कोई क्लाउड नहीं। प्लगइन और स्टैंडअलोन ऐप कभी ऑनलाइन नहीं जाते, और अगर कभी नेटवर्किंग कोड जोड़ा जाए तो एक बिल्ड गेट फेल हो जाता है।","featuresPage.coming.title":"अभी क्या आना बाक़ी है","featuresPage.coming.intro":"साफ़-साफ़ कहा गया, क्योंकि जो फ़ीचर सूची अपनी कमियाँ छिपाए, वह पढ़ने लायक नहीं। यह पन्ना संस्करण 1.0 के बारे में है, और Handscore एक-एक संस्करण करके बनाया जा रहा है, इसलिए इसका ज़्यादातर हिस्सा अभी बना नहीं है। 1.0 की ओर रास्ते का हर संस्करण अपनी स्थिति के साथ चिह्नित है।","featuresPage.limits.title":"1.0 क्या नहीं करता","featuresPage.limits.export":"यह MIDI या शीट म्यूज़िक को न सहेजता है, न एक्सपोर्ट करता है, न प्रिंट करता है: कोई हिस्सा Handscore से सिर्फ़ आपके DAW में खींचे जाने पर ही बाहर जाता है।","featuresPage.limits.families":"यह पियानो, गिटार और बास गिटार बजाता है। वाद्यों का हर दूसरा परिवार 1.0 के बाद एक-एक संस्करण करके आता है, 2.0 में पूरे बैंड तक।","featuresPage.limits.learn":"यह आपके साथ नहीं बजाता: आपके अपने कीबोर्ड पर साथ बजाना, और सीखने का मोड, संस्करण 1.9 में आते हैं।","featuresPage.coming.downloads":"संस्करण 1.0 से पहले कोई डाउनलोड नहीं है, और इस पन्ने पर भी कोई नहीं।","docs.intro":"यह मैनुअल हर संस्करण के साथ बढ़ता है। अभी यह बताता है कि संस्करण 0.2.0 क्या करता है।","docs.start.title":"शुरुआत करना","docs.agreement.title":"लाइसेंस अनुबंध","docs.stage.title":"मंच","docs.pianos.title":"पियानो","docs.play.title":"कुंजियाँ बजाना","docs.theme.title":"लाइट और डार्क","docs.language.title":"भाषाएँ","docs.privacy.title":"आपकी निजता","docs.start.p1":"Handscore आपके DAW के अंदर CLAP, VST3 या AU इंस्ट्रूमेंट के रूप में, या अकेले एक स्टैंडअलोन ऐप के रूप में चलता है। इसे किसी इंस्ट्रूमेंट ट्रैक पर रखें।","docs.start.p2":"संस्करण 1.0.0 से पहले कोई डाउनलोड नहीं है, और सोर्स कोड निजी है।","docs.agreement.p1":"Handscore जब पहली बार खुलता है, तो अपना लाइसेंस अनुबंध दिखाता है। जब तक आप सहमत नहीं चुनते, Handscore कुछ नहीं करता और कोई आवाज़ नहीं निकालता।","docs.agreement.p2":"आपका जवाब आपके कंप्यूटर पर रखा जाता है और Handscore की हर खुली कॉपी द्वारा साझा किया जाता है, हर DAW में और स्टैंडअलोन ऐप में भी। यदि आप अस्वीकार करते हैं, तो अनुबंध स्क्रीन पर बना रहता है, ताकि जब भी आप सहमत हों, वह तैयार रहे।","docs.stage.p1":"ऊपरी बार के नीचे मंच है: आपका चुना हुआ पियानो, उसकी 88 कुंजियाँ, A0 से C8 तक, असली पियानो के माप में, जो विंडो की पूरी चौड़ाई भरता है। हर कुंजी का नाम उसके सामने वाले हिस्से पर लिखा है — सफ़ेद कुंजियों पर गहरी स्याही में, काली कुंजियों पर सफ़ेद में — और कुंजी दबी रहने तक छिपा रहता है, ताकि आप हमेशा देख सकें कि कौन-से नोट बजाए जा रहे हैं।","docs.stage.p2":"अगर आपका कंप्यूटर 3D में नहीं बना सकता, तो मंच कुछ भी न दिखाने के बजाय यह बताता है और समझाता है कि इसे कैसे चालू करें।","docs.stage.p3":"Handscore मापता है कि आपका कंप्यूटर मंच को कितनी तेज़ी से बनाता है, और उस गुणवत्ता पर टिक जाता है जिसे वह सहजता से बनाए रख सके।","docs.pianos.p1":"चार पियानो बारी-बारी से मंच पर आते हैं, एक बार में एक: Grand Piano, Acoustic Piano, Upright Piano और Honky-Tonk Piano, हर एक का अपना आकार, फ़िनिश और आवाज़।","docs.pianos.p2":"ऊपर बाईं ओर का वाद्य बटन (या P) पियानो पिकर खोलता है। पूर्वावलोकन पियानो बदले बिना किसी पियानो पर एक छोटी धुन बजाता है; चुनें उसे मंच पर रख देता है, पिछले पियानो से क्रॉसफ़ेड करते हुए। आपकी पसंद आपके प्रोजेक्ट के साथ सहेजी जाती है।","docs.play.p1":"किसी कुंजी को सुनने के लिए उस पर क्लिक करें, या कुंजियों पर से सरकाते हुए उन्हें एक-एक करके बजाएँ। हर कुंजी अपने संतुलन बिंदु पर घूमते हुए नीचे जाती है, जितनी ज़ोर से बजाई जाए उतनी तेज़ी से, और नीचे रहने तक उसका नाम धुंधला रहता है और ऊपर उठने पर लौट आता है।","docs.play.p2":"आपके DAW से आने वाला MIDI पियानो बजाता है और उसकी कुंजियाँ हिलाता है। सस्टेन पेडल आपके छोड़े हुए सुरों को तब तक थामे रखता है जब तक आप उससे पैर नहीं उठा लेते।","docs.theme.p1":"ऊपर दाईं ओर का डार्क थीम स्विच विंडो को लाइट या डार्क करता है। Handscore आपकी पसंद याद रखता है, और आपके कंप्यूटर पर बाकी Freally ऐप्स भी।","docs.language.p1":"Handscore अठारह भाषाएँ बोलता है और आपके सिस्टम की भाषा में शुरू होता है।","docs.privacy.p1":"प्लगइन और स्टैंडअलोन ऐप कभी नेटवर्क का उपयोग नहीं करते। अगर Handscore कभी अचानक रुक जाए, तो एक छोटी रिपोर्ट आपके कंप्यूटर पर रखी जाती है और अगली बार इसके खुलने पर आपको पेश की जाती है; जब तक आप इसे रिपोर्ट करना नहीं चुनते, कुछ नहीं भेजा जाता।","kit.skip":"सामग्री पर जाएँ","kit.nav.site":"साइट","kit.nav.home":"होम","kit.nav.features":"फ़ीचर्स","kit.nav.documentation":"दस्तावेज़ीकरण","kit.nav.changelog":"बदलाव लॉग","kit.nav.language":"भाषा","kit.nav.allApps":"सभी Freally ऐप्स","kit.badge.progress":"v0.2.0 पूरा · आगे v0.3.0","kit.cta.features":"सभी फ़ीचर्स देखें","kit.cta.docs":"दस्तावेज़ीकरण पढ़ें","kit.price":"Freally Handscore आज मुफ़्त है, लेकिन हो सकता है कि यह हमेशा मुफ़्त न रहे: भविष्य के संस्करण बेचे जा सकते हैं।","kit.noDownloads":"अभी कोई डाउनलोड नहीं है, और सोर्स कोड निजी है।","kit.label.overview":"अवलोकन","kit.label.inside":"अंदर","kit.label.roadmap":"रोडमैप","kit.ladder.done":"पूरा","kit.ladder.planned":"नियोजित","kit.ladder.goal":"लक्ष्य","kit.ladder.later":"बाद में","kit.label.honesty":"ईमानदारी","kit.family.label":"Freally परिवार","kit.family.title":"<span class=\"hl-muted\">एक परिवार।</span> <span class=\"hl-bright\">दस ऐप्स।</span>","kit.cta.label":"क्या बदला","kit.cta.title":"<span class=\"hl-muted\">हर संस्करण,</span> <span class=\"hl-bright\">लिखित में।</span>","kit.cta.lede":"बदलाव लॉग में Freally Handscore में हुआ हर बदलाव, संस्करण-दर-संस्करण, सभी अठारह भाषाओं में दर्ज है।","kit.cta.changelog":"बदलाव लॉग पढ़ें","kit.footer.thisApp":"यह ऐप","kit.footer.family":"Freally परिवार","kit.status.devVersion":"विकास में · v0.2.0","kit.head.features":"<span class=\"hl-muted\">यह जो कुछ करता है,</span> <span class=\"hl-bright\">आमने-सामने।</span>","kit.label.numbers":"आँकड़ों में","kit.numbers.lead":"हर आँकड़ा ऐप से ही गिना गया है। कुछ भी अनुमानित नहीं है, और कुछ भी बढ़ाकर पूर्णांकित नहीं किया गया है।","kit.label.free":"आज मुफ़्त","kit.label.compare":"तुलना","kit.label.principles":"सिद्धांत","kit.label.limits":"सीमाएँ","kit.states.title":"स्थितियों का अर्थ","kit.states.done":"बना और टैग किया गया, पर इस साइट पर डाउनलोड नहीं","kit.states.planned":"अभी बनना बाकी है","kit.states.goal":"वह संस्करण जिस तक यह रास्ता जाता है","kit.states.later":"उसके बाद, और अभी तय नहीं","kit.states.ladder":"रास्ते का हर पड़ाव देखें","kit.head.documentation":"<span class=\"hl-muted\">यह कैसे काम करता है,</span> <span class=\"hl-bright\">क़दम-दर-क़दम।</span>","kit.search.placeholder":"दस्तावेज़ीकरण में खोजें","kit.docs.contents":"विषय-सूची","kit.head.changelog":"<span class=\"hl-muted\">हर बदलाव,</span> <span class=\"hl-bright\">संस्करण-दर-संस्करण।</span>","kit.changelog.lede":"सबसे नया पहले: Freally Handscore में जो कुछ बदला, इस साइट की हर भाषा में।","kit.changelog.versions":"संस्करण","kit.search.none":"इस साइट पर इससे कुछ भी मेल नहीं खाता।","kit.zoom.close":"बंद करें","changelog.c59c86e0cd28":"<span class=\"release__meta\"><span class=\"release__ver\">v0.2.0</span><time class=\"release__date\" datetime=\"2026-10-14\">2026-10-14</time></span>","changelog.14c84d5c455f":"असली पियानो। Handscore के मंच पर अब चार पियानो हैं — एक कॉन्सर्ट ग्रैंड, एक पार्लर ग्रैंड, एक स्टूडियो अपराइट और एक पुराना सलून अपराइट — हर एक स्टूडियो जैसी रोशनी में और हर एक की अपनी आवाज़। किसी कुंजी पर क्लिक करें या अपने DAW से बजाएँ, और पियानो बज उठता है: कुंजी नीचे जाती है, उसका नाम धुंधला पड़ जाता है, और सस्टेन पेडल वह थामे रखता है जो आप छोड़ देते हैं। पियानो पिकर से आप कोई पियानो चुनने से पहले उसे सुन सकते हैं।","changelog.6b02e0d363a4":"जोड़ा गया","changelog.a8f76e859570":"<strong>चार असली पियानो।</strong> Grand Piano, Acoustic Piano, Upright Piano और Honky-Tonk Piano, हर एक का अपना आकार, फ़िनिश और आवाज़, दोनों थीम में।","changelog.6f544a8bd67f":"<strong>कुंजियाँ बजाएँ।</strong> किसी कुंजी को सुनने के लिए उस पर क्लिक करें, या कुंजियों पर से सरकाते हुए उन्हें एक-एक करके बजाएँ। आपके DAW से आने वाला MIDI पियानो बजाता है और उसकी कुंजियाँ हिलाता है, और सस्टेन पेडल आपके छोड़े हुए सुरों को तब तक थामे रखता है जब तक आप उससे पैर नहीं उठा लेते।","changelog.3f265130a08f":"<strong>पियानो जैसी चलने वाली कुंजियाँ।</strong> हर कुंजी अपने संतुलन बिंदु पर घूमते हुए नीचे जाती है, जितनी ज़ोर से बजाई जाए उतनी तेज़ी से, और नीचे रहने तक उसका नाम धुंधला रहता है और ऊपर उठने पर लौट आता है।","changelog.7fd2c1ed940d":"<strong>पियानो पिकर।</strong> ऊपर बाईं ओर का वाद्य बटन (या P) चार कार्ड खोलता है। <em>पूर्वावलोकन</em> पियानो बदले बिना उस पियानो पर एक छोटी धुन बजाता है; <em>चुनें</em> उसे मंच पर रख देता है, पिछले पियानो से क्रॉसफ़ेड करते हुए। आपकी पसंद आपके प्रोजेक्ट के साथ सहेजी जाती है।","changelog.72aa386a33ff":"<strong>आपके कंप्यूटर के अनुरूप गुणवत्ता।</strong> Handscore मापता है कि आपका कंप्यूटर मंच को कितनी तेज़ी से बनाता है, और उस गुणवत्ता पर टिक जाता है जिसे वह सहजता से बनाए रख सके।","changelog.1246fc93bca0":"ठीक किया गया","changelog.58e041aeca75":"<strong>व्यस्त कंप्यूटर पर भी कुंजियाँ पीछे नहीं रहतीं।</strong> जब कंप्यूटर धीरे बना रहा होता था, तब बजाई गई कुंजी ऊपर ही रह सकती थी, या उसका नाम आधा धुंधला रह सकता था; अब वह हमेशा वहीं रुकती है जहाँ आपके बजाने ने उसे छोड़ा।","changelog.e6eef73c000a":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.0</span><time class=\"release__date\" datetime=\"2026-10-12\">2026-10-12</time></span>","changelog.ff94e0b1d59f":"नींव। Freally Handscore CLAP और VST3 प्लगइन के रूप में और स्टैंडअलोन ऐप के रूप में लोड होता है, अपने लाइसेंस की स्वीकृति माँगता है, और अपने मंच पर खुलता है: असली पियानो के माप में 88 कुंजियों वाला कीबोर्ड, जिसकी हर कुंजी का नाम उसके सामने वाले हिस्से पर लिखा है। अभी कुछ भी जनरेट नहीं होता — वह असली पियानो और हाथों के साथ आएगा।","changelog.37cee751dc57":"<strong>प्लगइन और स्टैंडअलोन ऐप।</strong> Windows पर CLAP और VST3 (AU एक Mac पर बनाया जाता है), और एक स्टैंडअलोन ऐप जो अपने टाइटल बार और टास्कबार में Handscore का आइकन दिखाता है।","changelog.bf0d03d43bfd":"<strong>लाइसेंस अनुबंध सबसे पहले।</strong> जब तक आप सहमत नहीं होते, Handscore कुछ नहीं करता। आपका जवाब आपके कंप्यूटर पर रखा जाता है और हर खुली कॉपी द्वारा साझा किया जाता है, हर DAW में और स्टैंडअलोन ऐप में भी।","changelog.28bc52fb055e":"<strong>मंच।</strong> 88 कुंजियों वाला कीबोर्ड, A0 से C8 तक, असली पियानो के माप में, जो विंडो की पूरी चौड़ाई भरता है। हर कुंजी का नाम उसके सामने वाले हिस्से पर लिखा है — सफ़ेद कुंजियों पर गहरी स्याही में, काली कुंजियों पर सफ़ेद में — और कुंजी दबी रहने तक छिपा रहता है।","changelog.d51fdbedfc0e":"<strong>लाइट और डार्क।</strong> ऊपर दाईं ओर का स्विच; Handscore आपकी पसंद याद रखता है।","changelog.9e0609310c1a":"<strong>अठारह भाषाएँ।</strong> Handscore आपके सिस्टम की भाषा में शुरू होता है।","changelog.f1cf7c9dfaa8":"<strong>एक 3D व्यू जो बताता है कि वह कब नहीं बना सकता।</strong> WebGL 2 के बिना कोई विंडो कुछ भी न दिखाने के बजाय समझाती है कि इसे कैसे चालू करें।","changelog.0fe089d138d3":"<strong>क्रैश रखे जाते हैं, कभी भेजे नहीं जाते।</strong> अगर Handscore कभी अचानक रुक जाए, तो अगली बार शुरू होने के लिए एक छोटी रिपोर्ट आपके कंप्यूटर पर रखी जाती है। जब तक आप इसे रिपोर्ट करना नहीं चुनते, आपके कंप्यूटर से कुछ भी बाहर नहीं जाता।"};
